'use client';

import React, { useState } from 'react';
import type { ProjectFormData } from '../page';
import { supabase } from '../../../../lib/supabase';
import { ArrowRightIcon, ArrowLeftIcon, PlusIcon, TrashIcon, PhotoIcon, XMarkIcon } from '@heroicons/react/24/outline';
import BHKTypeDropdown from '../../../components/BHKTypeDropdown';

const priceUnits = ['Rupees', 'Lakhs', 'Crores'];

interface Model {
  bhk_type: string;
  super_built_up_area: number;
  carpet_area: number;
  price: number;
  price_unit: string;
  price_per_sqft: number;
  price_per_sqft_unit: string;
  availability_status: 'available' | 'sold_out' | 'coming_soon';
  floor_plan_url: string;
  specifications: {
    bedrooms: number;
    bathrooms: number;
    balconies: number;
    parking: number;
  };
}

const emptyModel: Model = {
  bhk_type: '',
  super_built_up_area: 0,
  carpet_area: 0,
  price: 0,
  price_unit: 'Rupees',
  price_per_sqft: 0,
  price_per_sqft_unit: 'Rupees',
  availability_status: 'available',
  floor_plan_url: '',
  specifications: {
    bedrooms: 0,
    bathrooms: 0,
    balconies: 0,
    parking: 0,
  },
};

interface ModelsPricingProps {
  formData: {
    models: Model[];
    [key: string]: any;
  };
  updateFormData: (data: Partial<{ models: Model[] }>) => void;
  onNext: () => void;
  onBack: () => void;
  projectId?: string;
}

const ModelsPricing: React.FC<ModelsPricingProps> = ({ formData, updateFormData, onNext, onBack, projectId }) => {
  const [errors, setErrors] = useState<string | null>(null);
  const [uploadingIdx, setUploadingIdx] = useState<number | null>(null);
  const [uploadError, setUploadError] = useState<string | null>(null);

  const handleModelChange = (idx: number, field: string, value: any) => {
    // For numerical fields, convert empty string to 0
    if ((field === 'price' || field === 'price_per_sqft' || field === 'super_built_up_area' || field === 'carpet_area') 
        && (value === '' || isNaN(value))) {
      value = 0;
    }
    
    const updatedModels = formData.models.map((model, i) =>
      i === idx ? { ...model, [field]: value } : model
    );
    updateFormData({ models: updatedModels });
  };

  const handleSpecChange = (idx: number, spec: string, value: any) => {
    // Convert empty string to 0 for numerical specifications
    if (value === '' || isNaN(value)) {
      value = 0;
    }
    
    const updatedModels = formData.models.map((model, i) =>
      i === idx ? { ...model, specifications: { ...model.specifications, [spec]: value } } : model
    );
    updateFormData({ models: updatedModels });
  };

  const addModel = () => {
    updateFormData({ models: [...formData.models, { ...emptyModel }] });
  };

  const removeModel = (idx: number) => {
    updateFormData({ models: formData.models.filter((_, i) => i !== idx) });
  };

  const handleNext = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.models.length === 0) {
      setErrors('Please add at least one model.');
      return;
    }
    setErrors(null);
    onNext();
  };

  // Floor plan upload with structured path
  const handleFloorPlanUpload = async (idx: number, file: File) => {
    setUploadingIdx(idx);
    setUploadError(null);
    const ext = file.name.split('.').pop();
    // Try to get projectId from props, modelId if available, fallback to bhk_type
    const project = projectId || 'unknown-project';
    const model = formData.models[idx];
    const modelId = (model as any).id || model.bhk_type || `model${idx+1}`;
    const fileName = `floorplan-${Date.now()}.${ext}`;
    const filePath = `${project}/${modelId}/${fileName}`;
    const { data, error } = await supabase.storage.from('floorplans').upload(filePath, file, { upsert: true });
    if (error) {
      setUploadError('Failed to upload image.');
      setUploadingIdx(null);
      return;
    }
    // Get public URL
    const { data: publicUrlData } = supabase.storage.from('floorplans').getPublicUrl(filePath);
    const url = publicUrlData?.publicUrl || '';
    handleModelChange(idx, 'floor_plan_url', url);
    setUploadingIdx(null);
  };

  const handleRemoveFloorPlan = (idx: number) => {
    handleModelChange(idx, 'floor_plan_url', '');
  };

  return (
    <form onSubmit={handleNext} className="space-y-8">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">Models & Pricing</label>
        {formData.models.length === 0 && (
          <div className="text-gray-400 text-sm mb-2">No models added yet.</div>
        )}
        <div className="space-y-8">
          {formData.models.map((model, idx) => (
            <div key={idx} className="border border-gray-200 rounded-lg p-4 relative bg-gray-50">
              <button
                type="button"
                className="absolute top-2 right-2 text-red-500 hover:text-red-700"
                onClick={() => removeModel(idx)}
                title="Remove model"
              >
                <TrashIcon className="w-5 h-5" />
              </button>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1">BHK Type</label>
                  <BHKTypeDropdown
                    selectedBHK={model.bhk_type}
                    onChange={value => handleModelChange(idx, 'bhk_type', value)}
                    placeholder="Select BHK Type"
                    className="w-full"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1">Super Built-up Area (sq.ft.)</label>
                  <input
                    type="number"
                    className="w-full rounded-lg border border-gray-300 px-3 py-2"
                    placeholder="e.g. 1200"
                    value={model.super_built_up_area}
                    onChange={e => handleModelChange(idx, 'super_built_up_area', parseFloat(e.target.value))}
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1">Carpet Area (sq.ft.)</label>
                  <input
                    type="number"
                    className="w-full rounded-lg border border-gray-300 px-3 py-2"
                    placeholder="e.g. 900"
                    value={model.carpet_area}
                    onChange={e => handleModelChange(idx, 'carpet_area', parseFloat(e.target.value))}
                  />
                </div>
                <div className="flex gap-2 items-end">
                  <div className="flex-1">
                    <label className="block text-xs font-medium text-gray-700 mb-1">Price</label>
                    <input
                      type="number"
                      className="w-full rounded-lg border border-gray-300 px-3 py-2"
                      placeholder="e.g. 1.25"
                      value={model.price}
                      onChange={e => handleModelChange(idx, 'price', parseFloat(e.target.value))}
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Unit</label>
                    <select
                      className="rounded-lg border border-gray-300 px-2 py-2"
                      value={model.price_unit || 'Rupees'}
                      onChange={e => handleModelChange(idx, 'price_unit', e.target.value)}
                    >
                      {priceUnits.map(unit => (
                        <option key={unit} value={unit}>{unit}</option>
                      ))}
                    </select>
                  </div>
                </div>
                <div className="flex gap-2 items-end">
                  <div className="flex-1">
                    <label className="block text-xs font-medium text-gray-700 mb-1">Price per Sq.Ft.</label>
                    <input
                      type="number"
                      className="w-full rounded-lg border border-gray-300 px-3 py-2"
                      placeholder="e.g. 5000"
                      value={model.price_per_sqft}
                      onChange={e => handleModelChange(idx, 'price_per_sqft', parseFloat(e.target.value))}
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Unit</label>
                    <select
                      className="rounded-lg border border-gray-300 px-2 py-2"
                      value={model.price_per_sqft_unit || 'Rupees'}
                      onChange={e => handleModelChange(idx, 'price_per_sqft_unit', e.target.value)}
                    >
                      {priceUnits.map(unit => (
                        <option key={unit} value={unit}>{unit}</option>
                      ))}
                    </select>
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-medium text-gray-700 mb-1">Availability Status</label>
                  <select
                    className="w-full rounded-lg border border-gray-300 px-3 py-2"
                    value={model.availability_status}
                    onChange={e => handleModelChange(idx, 'availability_status', e.target.value as 'available' | 'sold_out' | 'coming_soon')}
                  >
                    <option value="available">Available</option>
                    <option value="sold_out">Sold Out</option>
                    <option value="coming_soon">Coming Soon</option>
                  </select>
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Bedrooms</label>
                    <input
                      type="number"
                      className="w-full rounded-lg border border-gray-300 px-3 py-2"
                      value={model.specifications.bedrooms}
                      onChange={e => handleSpecChange(idx, 'bedrooms', parseInt(e.target.value))}
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Bathrooms</label>
                    <input
                      type="number"
                      className="w-full rounded-lg border border-gray-300 px-3 py-2"
                      value={model.specifications.bathrooms}
                      onChange={e => handleSpecChange(idx, 'bathrooms', parseInt(e.target.value))}
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Balconies</label>
                    <input
                      type="number"
                      className="w-full rounded-lg border border-gray-300 px-3 py-2"
                      value={model.specifications.balconies}
                      onChange={e => handleSpecChange(idx, 'balconies', parseInt(e.target.value))}
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-gray-700 mb-1">Parking</label>
                    <input
                      type="number"
                      className="w-full rounded-lg border border-gray-300 px-3 py-2"
                      value={model.specifications.parking}
                      onChange={e => handleSpecChange(idx, 'parking', parseInt(e.target.value))}
                    />
                  </div>
                </div>
                {/* Floor Plan Image Upload */}
                <div className="md:col-span-2">
                  <label className="block text-xs font-medium text-gray-700 mb-1">Floor Plan Image</label>
                  {model.floor_plan_url ? (
                    <div className="flex items-center gap-4 mb-2">
                      <img src={model.floor_plan_url} alt="Floor Plan" className="w-32 h-24 object-contain rounded border" />
                      <button
                        type="button"
                        className="inline-flex items-center px-2 py-1 bg-red-100 text-red-700 rounded hover:bg-red-200 text-xs"
                        onClick={() => handleRemoveFloorPlan(idx)}
                      >
                        <XMarkIcon className="w-4 h-4 mr-1" /> Remove
                      </button>
                    </div>
                  ) : null}
                  <div className="flex items-center gap-2">
                    <label className="inline-flex items-center cursor-pointer">
                      <input
                        type="file"
                        accept="image/*"
                        className="hidden"
                        onChange={e => {
                          if (e.target.files && e.target.files[0]) {
                            handleFloorPlanUpload(idx, e.target.files[0]);
                          }
                        }}
                        disabled={uploadingIdx === idx}
                      />
                      <span className="inline-flex items-center px-3 py-2 bg-green-100 text-green-700 rounded-lg shadow hover:bg-green-200 text-xs font-medium">
                        <PhotoIcon className="w-4 h-4 mr-1" />
                        {uploadingIdx === idx ? 'Uploading...' : model.floor_plan_url ? 'Replace Image' : 'Upload Image'}
                      </span>
                    </label>
                    {uploadError && uploadingIdx === idx && (
                      <span className="text-xs text-red-500 ml-2">{uploadError}</span>
                    )}
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>
        <button
          type="button"
          className="mt-4 inline-flex items-center px-4 py-2 bg-green-100 text-green-700 font-semibold rounded-lg shadow hover:bg-green-200 transition-colors"
          onClick={addModel}
        >
          <PlusIcon className="w-5 h-5 mr-2" /> Add Model
        </button>
        {errors && <p className="text-xs text-red-500 mt-2">{errors}</p>}
      </div>
      <div className="flex justify-between pt-4">
        <button
          type="button"
          onClick={onBack}
          className="inline-flex items-center px-6 py-2 bg-gray-200 text-gray-700 font-semibold rounded-lg shadow hover:bg-gray-300 transition-colors focus:outline-none focus:ring-2 focus:ring-green-500"
        >
          <ArrowLeftIcon className="w-5 h-5 mr-2" />
          Back
        </button>
        <button
          type="submit"
          className="inline-flex items-center px-6 py-2 bg-green-600 text-white font-semibold rounded-lg shadow hover:bg-green-700 transition-colors focus:outline-none focus:ring-2 focus:ring-green-500"
        >
          Next
          <ArrowRightIcon className="w-5 h-5 ml-2" />
        </button>
      </div>
    </form>
  );
};

export default ModelsPricing;
